// JAH demo program - run with: node demo.js (or paste into a browser console)
// Demo: Memory Resource Monitor - public implementations survey
(function(){'use strict';
var DATA={"label": "Memory Resource Monitor - public implementations survey", "prog": [["PUSH", 4], ["PUSH", 7], ["ADD"], ["PUSH", 3], ["MUL"], ["PRINT"]]};

var stack=[],pc=0,prog=DATA.prog;
console.log('Mini-VM trace ('+DATA.label+'):');
while(pc<prog.length){var ins=prog[pc];
  if(ins[0]==='PUSH')stack.push(ins[1]);
  else if(ins[0]==='ADD'){var b=stack.pop(),a=stack.pop();stack.push(a+b);}
  else if(ins[0]==='SUB'){var b2=stack.pop(),a2=stack.pop();stack.push(a2-b2);}
  else if(ins[0]==='MUL'){var b3=stack.pop(),a3=stack.pop();stack.push(a3*b3);}
  else if(ins[0]==='DIV'){var b4=stack.pop(),a4=stack.pop();stack.push(a4/b4);}
  else if(ins[0]==='DUP')stack.push(stack[stack.length-1]);
  else if(ins[0]==='PRINT')console.log('  PRINT -> '+stack[stack.length-1]);
  console.log('  ['+pc+'] '+ins[0]+(ins[1]!==undefined?' '+ins[1]:'')+'   stack=['+stack.join(', ')+']');
  pc++;}
console.log('OK - halted with stack ['+stack.join(', ')+']');
})();

